def roman_to_int_strict(s: str) -> int:
    # Define a dictionary of Roman numeral values
    roman_dict = {
        'M': 1000, 'CM': 900, 'D': 500, 'CD': 400, 'C': 100, 'XC': 90,
        'L': 50, 'XL': 40, 'X': 10, 'IX': 9, 'V': 5, 'IV': 4, 'I': 1
    }

    # Define a helper function to check if a Roman numeral is valid
    def is_valid_roman(roman: str) -> bool:
        return len(roman) > 0 and all(c in roman_dict.values() for c in roman)

    # Check if the input string is a valid Roman numeral
    if not is_valid_roman(s):
        return -1

    # Remove any leading or trailing spaces from the Roman numeral string
    s = s.strip()

    # Split the Roman numeral string into a list of Roman numeral values
    values = [roman_dict[c] for c in s if c in roman_dict.keys()]

    # Convert the list of Roman numeral values to an integer
    return sum(values)

def text_justify(words: list[str], width: int) -> list[str]:
    # Function to calculate the number of spaces needed to fill a given width
    def spaces(width: int) -> int:
        return (width - len(str(width))) // 2 + 1

    # Function to join words with spaces and fit within a given width
    def justify_words(words: list[str], width: int) -> list[str]:
        result = []
        for word in words:
            spaces_needed = spaces(width)
            if len(word) + spaces_needed > width:
                spaces_needed -= len(word)
                word = word + ' ' * spaces_needed
            result.append(word + ' ' * spaces_needed)
        return result

    # Join the justified words into a single string
    return ' '.join(justify_words(words, width))

