from collections import defaultdict, deque

def merge_intervals(intervals: list[list[int]]):
    interval_dict = defaultdict(deque)

    for interval in intervals:
        interval_dict[min(interval)].append(max(interval))

    merged_intervals = []
    for interval in interval_dict.values():
        merged_intervals.append(list(interval))

    return sorted(merged_intervals, key=lambda x: x[0])

