def count_islands(grid: list[str]) -> int:
    rows, cols = len(grid), len(grid[0])
    island_count = 0

    def dfs(x, y):
        nonlocal island_count
        if grid[y][x] == '0':
            return

        grid[y][x] = '0'
        dfs(x + 1, y)
        dfs(x - 1, y)
        dfs(x, y + 1)
        dfs(x, y - 1)

    for y in range(rows):
        for x in range(cols):
            if grid[y][x] == '1':
                dfs(x, y)
                island_count += 1

    return island_count
